package br.com.pelotavision;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.util.*;import java.io.*;import java.nio.file.*;import org.json.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=33,manifest=Config.NONE,qualifiers="w400dp-h820dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ActiveRoiDemoTest {
 @Test public void realRoiIsTheOnlyPhotoOnMainScreenBeforeAndAfterSegmentation()throws Exception{
  File dir=new File(System.getProperty("pelotavision.validationDir"),"roi-active-0.10.0");JSONObject input=new JSONObject(new String(Files.readAllBytes(new File(dir,"analysis.json").toPath()),java.nio.charset.StandardCharsets.UTF_8));Bitmap photo=BitmapFactory.decodeFile(new File(dir.getParentFile(),"belt-0.9.0/input_correia.jpg").toString());assertNotNull(photo);List<PelletDetector.Detection> objects=new ArrayList<>();List<CrackAnalysis.Entry> entries=new ArrayList<>();JSONArray ds=input.getJSONArray("objects");
  for(int i=0;i<ds.length();i++){JSONObject d=ds.getJSONObject(i);PelletDetector.Detection seed=new PelletDetector.Detection(d.getDouble("crack_x"),d.getDouble("crack_y"),d.getDouble("crack_radius"),Math.PI*Math.pow(d.getDouble("crack_radius"),2),d.getDouble("roundness"),d.getBoolean("partial"),d.getBoolean("crack_review"));objects.add(new PelletDetector.Detection(seed,d.getDouble("x"),d.getDouble("y"),d.getDouble("a"),d.getDouble("b"),d.getDouble("angle"),d.getBoolean("fitted"),d.isNull("support")?Double.NaN:d.getDouble("support"),d.isNull("rms")?Double.NaN:d.getDouble("rms"),d.getBoolean("partial"),d.getBoolean("review")));JSONArray rs=d.getJSONArray("crack_runs");float[] runs=new float[rs.length()];for(int j=0;j<runs.length;j++)runs[j]=(float)rs.getDouble(j);entries.add(new CrackAnalysis.Entry(i+1,CrackAnalysis.Status.valueOf(d.getString("crack_status")),runs,d.isNull("crack_score")?Double.NaN:d.getDouble("crack_score"),"random_forest_20261018_v1"));}

  PelletDetector.Result all=new PelletDetector.Result(objects,photo.getWidth(),photo.getHeight(),objects.size(),0,false,input.getString("method"));CrackAnalysis cracks=new CrackAnalysis(all.width,all.height,50,0,entries);InterestRegion roi=new InterestRegion(InterestRegion.Shape.RECTANGLE,440,340,860,940);AnalysisWindow window=new AnalysisWindow(all.width,all.height,roi);for(PelletDetector.Detection d:objects)assertTrue(roi.includes(d));
  try(var ctl=Robolectric.buildActivity(MainActivity.class).setup()){
   MainActivity a=ctl.get();ObjectCalibrationTest.setup(a);Bitmap dummy=(Bitmap)ObjectCalibrationTest.get(a,"photoBitmap");ObjectCalibrationTest.set(a,"photoBitmap",photo);dummy.recycle();try(var stream=new FileInputStream(new File(dir.getParentFile().getParentFile(),"app/src/main/assets/crack_forest.pvrf"))){ObjectCalibrationTest.set(a,"crackModel",new CrackModel(stream));}ObjectCalibrationTest.set(a,"photoAllResult",all);ObjectCalibrationTest.set(a,"photoAllCracks",cracks);ObjectCalibrationTest.set(a,"originalWidth",photo.getWidth());ObjectCalibrationTest.set(a,"originalHeight",photo.getHeight());((View)ObjectCalibrationTest.get(a,"frozen")).setVisibility(View.VISIBLE);
   ObjectCalibrationTest.call(a,"activateRoi",new Class[]{InterestRegion.class},roi);render(a,new File(dir,"Tela_ROI_aplicada.png"));assertTrue((Boolean)ObjectCalibrationTest.get(a,"roiNeedsAnalysis"));assertFalse(((Button)ObjectCalibrationTest.get(a,"save")).isEnabled());Bitmap crop=(Bitmap)ObjectCalibrationTest.get(a,"displayBitmap");assertEquals(420,crop.getWidth());assertEquals(600,crop.getHeight());assertEquals(photo.getPixel(650,640),crop.getPixel(210,300));
   ObjectCalibrationTest.set(a,"roiNeedsAnalysis",false);ObjectCalibrationTest.set(a,"photoAnalysisWindow",window);ObjectCalibrationTest.call(a,"applyRegion",new Class[]{InterestRegion.class},roi);render(a,new File(dir,"Tela_ROI_segmentada.png"));assertTrue(((Button)ObjectCalibrationTest.get(a,"save")).isEnabled());assertEquals(objects.size(),((PelletDetector.Result)ObjectCalibrationTest.get(a,"photoResult")).circles.size());
   Bitmap report=PhotoComposer.compose(photo,all,cracks,null,roi,0,true);BeltDemoTest.png(report,new File(dir,"Relatorio_ROI_ativo.png"));report.recycle();
   CircleOverlay overlay=(CircleOverlay)ObjectCalibrationTest.get(a,"overlay");double scale=Math.min(overlay.getWidth()/420.,overlay.getHeight()/600.);double[] mapped=overlay.toPhoto(overlay.getWidth()/2f,overlay.getHeight()/2f);assertNotNull(mapped);assertEquals(650,mapped[0],.01);assertEquals(640,mapped[1],.01);
  }
 }
 static void render(MainActivity a,File path)throws Exception{View root=a.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(800,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1640,View.MeasureSpec.EXACTLY));root.layout(0,0,800,1640);android.graphics.Rect bounds=new android.graphics.Rect();Button save=(Button)ObjectCalibrationTest.get(a,"save");boolean visible=save.getGlobalVisibleRect(bounds);java.nio.file.Files.write(new File(path.getParentFile(),path.getName()+".layout.txt").toPath(),("save_visible="+visible+"; fullHeight="+save.getHeight()+"; visible="+bounds+"; root="+root.getHeight()+"; parent="+((View)save.getParent()).getBottom()).getBytes(java.nio.charset.StandardCharsets.UTF_8));assertTrue("Save action must remain fully reachable",visible&&bounds.height()>=save.getHeight());Bitmap b=Bitmap.createBitmap(800,1640,Bitmap.Config.ARGB_8888);root.draw(new Canvas(b));BeltDemoTest.png(b,path);b.recycle();}
}
